package nl.timtoys.corruptedadventure.registry;

import net.minecraft.core.registries.Registries;
import net.minecraft.resources.ResourceKey;
import net.minecraft.world.level.biome.Biome;
import nl.timtoys.corruptedadventure.CorruptedAdventure;

/**
 * Keys of the mod's biomes. The biomes themselves are datapack entries, generated by datagen.
 */
public final class ModBiomes {
    // Ring 2 (Ring2Biomes; Ring2Biomes.ALL lists every biome with ring 2 worldgen).
    public static final ResourceKey<Biome> CANYONLANDS = key("canyonlands");
    public static final ResourceKey<Biome> OASIS_FLATS = key("oasis_flats");
    public static final ResourceKey<Biome> HOODOO_FIELDS = key("hoodoo_fields");
    public static final ResourceKey<Biome> SALT_FLATS = key("salt_flats");
    public static final ResourceKey<Biome> DUNE_SEA = key("dune_sea");

    // Nether ring 2 (NetherRing2Biomes).
    public static final ResourceKey<Biome> DRIPSHROOM_FOREST = key("dripshroom_forest");
    public static final ResourceKey<Biome> SPORE_CAVES = key("spore_caves");

    // Ring 3 (Ring3Biomes; Ring3Biomes.ALL lists every biome with ring 3 worldgen; docs/plans/ring-3/contract.md §2).
    public static final ResourceKey<Biome> ASHEN_WASTES = key("ashen_wastes");
    public static final ResourceKey<Biome> VOLCANIC_PEAKS = key("volcanic_peaks");
    public static final ResourceKey<Biome> EMBER_WOODS = key("ember_woods");
    public static final ResourceKey<Biome> BASALT_FLOWS = key("basalt_flows");
    public static final ResourceKey<Biome> SULFUR_FIELDS = key("sulfur_fields");
    public static final ResourceKey<Biome> DRIED_SEABED = key("dried_seabed");
    public static final ResourceKey<Biome> TITAN_FIELDS = key("titan_fields");
    /** Micro-biome inside dormant calderas, chosen on the router's {@code weirdness}; a heat refuge. */
    public static final ResourceKey<Biome> DORMANT_CALDERA = key("dormant_caldera");
    /** Transition biome of boundary 3 (ring 3 | ring 4). */
    public static final ResourceKey<Biome> STEAM_FENS = key("steam_fens");

    // Nether ring 3 (NetherRing3Biomes, 53b).
    public static final ResourceKey<Biome> FROZEN_LAVA_SEA = key("frozen_lava_sea");
    public static final ResourceKey<Biome> RIME_FOREST = key("rime_forest");
    public static final ResourceKey<Biome> GLACIER_RIFTS = key("glacier_rifts");

    // Ring 4 (Ring4Biomes, 64; docs/plans/ring-4/contract.md §2).
    // Mythical band.
    public static final ResourceKey<Biome> CASCADE_VALE = key("cascade_vale");
    public static final ResourceKey<Biome> CRYSTAL_LAGOON = key("crystal_lagoon");
    public static final ResourceKey<Biome> LOTUS_SHALLOWS = key("lotus_shallows");
    public static final ResourceKey<Biome> GLOWROOT_SWAMP = key("glowroot_swamp");
    public static final ResourceKey<Biome> MIST_FJORDS = key("mist_fjords");
    // Blighted band.
    public static final ResourceKey<Biome> DROWNED_FOREST = key("drowned_forest");
    public static final ResourceKey<Biome> PEAT_MOORS = key("peat_moors");
    public static final ResourceKey<Biome> REED_MARSH = key("reed_marsh");
    /** Height biome: islands topping out at Y 140 or higher above the mythical band. */
    public static final ResourceKey<Biome> SKY_GARDENS = key("sky_gardens");
    /** Height biome: islands topping out at Y 140 or higher above the blighted band. */
    public static final ResourceKey<Biome> WITHERED_GARDENS = key("withered_gardens");
    /** Transition biome of boundary 4 (ring 4 | ring 5). */
    public static final ResourceKey<Biome> SUNDERED_REACH = key("sundered_reach");
    /**
     * Second transition biome of boundary 3 (ring 3 | ring 4): the descent outside the {@code steam_fens} strip
     * ({@code transition_splits.ring_3}; docs/plans/ring-4/verdant-falls.md). Key only until W-biomes adds the biome.
     */
    public static final ResourceKey<Biome> VERDANT_FALLS = key("verdant_falls");

    // Nether ring 4 (NetherRing4Biomes, 65). Keys only until then.
    public static final ResourceKey<Biome> BONE_DUNES = key("bone_dunes");
    public static final ResourceKey<Biome> CRYSTAL_SPIRES = key("crystal_spires");
    public static final ResourceKey<Biome> GEODE_HOLLOWS = key("geode_hollows");

    // Temporary: one per ring until the ring's real biomes exist. Ring 1's copies (overworld and Nether):
    // VanillaBiomeCopies.copyOf.
    public static final ResourceKey<Biome> PLACEHOLDER_RING_4 = key("placeholder_ring_4");
    public static final ResourceKey<Biome> PLACEHOLDER_RING_5 = key("placeholder_ring_5");
    public static final ResourceKey<Biome> PLACEHOLDER_NETHER_RING_4 = key("placeholder_nether_ring_4");
    public static final ResourceKey<Biome> PLACEHOLDER_NETHER_RING_5 = key("placeholder_nether_ring_5");

    // Transition biomes: one per boundary, filling its transition zone.
    public static final ResourceKey<Biome> WITHERED_EXPANSE = key("withered_expanse");
    // Listed in Ring2Biomes.ALL (ring 2 worldgen, tags), registered by TransitionBiomes.
    public static final ResourceKey<Biome> DRY_RIVERBEDS = key("dry_riverbeds");

    // Permanent: beyond ring 5 (floating islands, then void).
    public static final ResourceKey<Biome> VOID_EDGE = key("void_edge");
    public static final ResourceKey<Biome> NETHER_VOID_EDGE = key("nether_void_edge");

    private ModBiomes() {
    }

    private static ResourceKey<Biome> key(String path) {
        return ResourceKey.create(Registries.BIOME, CorruptedAdventure.id(path));
    }
}
